21	func newDoctorCmd() *cobra.Command {
22		var forceFlag bool
23	
24		cmd := &cobra.Command{
25			Use:   "doctor",
26			Short: "Diagnose and fix session issues",
27			Long: `Scan for session issues and offer to fix them.
28	
29	Checks performed:
30	  1. Disconnected metadata branches: detects when local and remote
31	     entire/checkpoints/v1 branches share no common ancestor (caused by a
32	     previous bug). Fixes by cherry-picking local checkpoints onto remote tip.
33	  2. Stuck sessions: sessions stuck in ACTIVE or ENDED phase that need cleanup.
34	
35	A session is considered stuck if:
36	  - It is in ACTIVE phase with no interaction for over 1 hour
37	  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch
38	
39	For each stuck session, you can choose to:
40	  - Condense: Save session data to permanent storage (entire/checkpoints/v1 branch)
41	  - Discard: Remove the session state and shadow branch data
42	  - Skip: Leave the session as-is
43	
44	Use --force to condense all fixable sessions without prompting.  Sessions that can't
45	be condensed will be discarded.`,
46			PreRun: func(_ *cobra.Command, _ []string) {
47				strategy.EnsureRedactionConfigured()
48			},
49			RunE: func(cmd *cobra.Command, _ []string) error {
50				return runSessionsFix(cmd, forceFlag)
51			},
52		}
53	
54		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Auto-fix all issues without prompting")
55	
56		return cmd
57	}
