59	// stuckSession holds a session state along with diagnostic info.
60	type stuckSession struct {
61		State             *strategy.SessionState
62		Reason            string
63		ShadowBranch      string
64		HasShadowBranch   bool
65		CheckpointCount   int
66		FilesTouchedCount int
67	}
