69	func runSessionsFix(cmd *cobra.Command, force bool) error {
70		var finalErr error
71	
72		// Check 1: Disconnected metadata branches
73		metadataErr := checkDisconnectedMetadata(cmd, force)
74		if metadataErr != nil {
75			fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
76			finalErr = NewSilentError(fmt.Errorf("metadata check failed: %w", metadataErr))
77		}
78		fmt.Fprintln(cmd.OutOrStdout())
79	
80		// Check 2: Stuck sessions
81		ctx := cmd.Context()
82		// Load all session states
83		states, err := strategy.ListSessionStates(ctx)
84		if err != nil {
85			return fmt.Errorf("failed to list session states: %w", err)
86		}
87	
88		if len(states) == 0 {
89			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
90			if finalErr != nil {
91				return finalErr
92			}
93			return nil
94		}
95	
96		// Open repository to check shadow branches (uses worktree-aware helper)
97		repo, err := openRepository(ctx)
98		if err != nil {
99			return fmt.Errorf("failed to open repository: %w", err)
100		}
101	
102		// Identify stuck sessions
103		now := time.Now()
104		var stuck []stuckSession
105	
106		for _, state := range states {
107			ss := classifySession(state, repo, now)
108			if ss != nil {
109				stuck = append(stuck, *ss)
110			}
111		}
112	
113		if len(stuck) == 0 {
114			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
115			if finalErr != nil {
116				return finalErr
117			}
118			return nil
119		}
120	
121		// Get the current strategy for condense operations
122		strat := GetStrategy(ctx)
123	
124		fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
125	
126		for _, ss := range stuck {
127			displayStuckSession(cmd, ss)
128	
129			if force {
130				if ss.HasShadowBranch && ss.CheckpointCount > 0 {
131					if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
132						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
133					} else {
134						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
135					}
136				} else {
137					// Discard if we can't condense
138					if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
139						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
140					} else {
141						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
142					}
143				}
144				continue
145			}
146	
147			// Interactive: prompt for action
148			action, err := promptSessionAction(ss)
149			if err != nil {
150				if errors.Is(err, huh.ErrUserAborted) {
151					return nil
152				}
153				return fmt.Errorf("failed to get action: %w", err)
154			}
155	
156			switch action {
157			case "condense":
158				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
159					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
160				} else {
161					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
162				}
163			case "discard":
164				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
165					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
166				} else {
167					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
168				}
169			case "skip":
170				fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
171			}
172		}
173	
174		if finalErr != nil {
175			return finalErr
176		}
177	
178		return nil
179	}
