181	// classifySession determines if a session is stuck and returns diagnostic info.
182	// Returns nil if the session is healthy.
183	func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
184		// Determine shadow branch info
185		shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
186		refName := plumbing.NewBranchReferenceName(shadowBranch)
187		_, refErr := repo.Reference(refName, true)
188		hasShadowBranch := refErr == nil
189	
190		switch {
191		case state.Phase.IsActive():
192			if !state.IsStuckActive() {
193				return nil
194			}
195	
196			var reason string
197			if state.LastInteractionTime != nil {
198				reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
199			} else {
200				reason = fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute))
201			}
202	
203			return &stuckSession{
204				State:             state,
205				Reason:            reason,
206				ShadowBranch:      shadowBranch,
207				HasShadowBranch:   hasShadowBranch,
208				CheckpointCount:   state.StepCount,
209				FilesTouchedCount: len(state.FilesTouched),
210			}
211	
212		case state.Phase == session.PhaseEnded:
213			// Ended sessions are stuck if they have uncondensed data
214			if state.StepCount <= 0 || !hasShadowBranch {
215				return nil
216			}
217	
218			return &stuckSession{
219				State:             state,
220				Reason:            "ended with uncondensed checkpoint data",
221				ShadowBranch:      shadowBranch,
222				HasShadowBranch:   hasShadowBranch,
223				CheckpointCount:   state.StepCount,
224				FilesTouchedCount: len(state.FilesTouched),
225			}
226	
227		default:
228			return nil
229		}
230	}
