232	// displayStuckSession prints diagnostic info for a stuck session.
233	func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
234		w := cmd.OutOrStdout()
235	
236		fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
237		fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
238		fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
239	
240		if ss.State.AgentType != "" {
241			fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
242		}
243	
244		if ss.State.LastInteractionTime != nil {
245			fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
246		}
247	
248		shadowStatus := "not found"
249		if ss.HasShadowBranch {
250			shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
251		}
252		fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
253		fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
254	}
