256	// promptSessionAction asks the user what to do with a stuck session.
257	func promptSessionAction(ss stuckSession) (string, error) {
258		var action string
259	
260		options := make([]huh.Option[string], 0, 3)
261		if ss.HasShadowBranch && ss.CheckpointCount > 0 {
262			options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
263		}
264		options = append(options,
265			huh.NewOption("Discard (remove session data)", "discard"),
266			huh.NewOption("Skip (leave as-is)", "skip"),
267		)
268	
269		form := NewAccessibleForm(
270			huh.NewGroup(
271				huh.NewSelect[string]().
272					Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
273					Options(options...).
274					Value(&action),
275			),
276		)
277	
278		if err := form.Run(); err != nil {
279			return "", fmt.Errorf("session fix prompt failed: %w", err)
280		}
281	
282		return action, nil
283	}
