285	// discardSession removes session state and cleans up the shadow branch.
286	func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
287		// Clear session state file
288		if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
289			return fmt.Errorf("failed to clear session state: %w", err)
290		}
291	
292		// Delete shadow branch if it exists and no other sessions need it
293		if ss.HasShadowBranch {
294			if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
295				fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
296			} else if shouldDelete {
297				if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
298					// Branch already gone is not an error — keeps discard idempotent
299					if !errors.Is(err, strategy.ErrBranchNotFound) {
300						return fmt.Errorf("failed to delete shadow branch: %w", err)
301					}
302				}
303			}
304		}
305	
306		return nil
307	}
