309	// checkDisconnectedMetadata detects and optionally repairs disconnected
310	// local/remote metadata branches (the "empty-orphan bug").
311	func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
312		repo, err := openRepository(cmd.Context())
313		if err != nil {
314			return fmt.Errorf("failed to open repository: %w", err)
315		}
316	
317		ctx := cmd.Context()
318		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
319		disconnected, err := strategy.IsMetadataDisconnected(ctx, repo, remoteRefName)
320		if err != nil {
321			return fmt.Errorf("could not check metadata branch state: %w", err)
322		}
323	
324		w := cmd.OutOrStdout()
325	
326		if !disconnected {
327			fmt.Fprintln(w, "✓ Metadata branches: OK")
328			return nil
329		}
330	
331		fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
332		fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
333		fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
334		fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
335	
336		if !force {
337			var confirmed bool
338			form := NewAccessibleForm(
339				huh.NewGroup(
340					huh.NewConfirm().
341						Title("Fix disconnected metadata branches?").
342						Value(&confirmed),
343				),
344			)
345			if formErr := form.Run(); formErr != nil {
346				if errors.Is(formErr, huh.ErrUserAborted) {
347					return nil
348				}
349				return fmt.Errorf("prompt failed: %w", formErr)
350			}
351			if !confirmed {
352				fmt.Fprintln(w, "  -> Skipped")
353				return nil
354			}
355		}
356	
357		if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, remoteRefName, cmd.ErrOrStderr()); fixErr != nil {
358			return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
359		}
360	
361		fmt.Fprintln(w, "  ✓ Fixed: metadata branches reconciled")
362		return nil
363	}
364	
365	// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
366	// Returns true if no other sessions (besides excludeSessionID) need this branch.
367	func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
368		states, err := strategy.ListSessionStates(ctx)
369		if err != nil {
370			return false, fmt.Errorf("failed to list session states: %w", err)
371		}
372	
373		for _, state := range states {
374			if state.SessionID == excludeSessionID {
375				continue
376			}
377			otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
378			if otherShadow == shadowBranch && state.StepCount > 0 {
379				return false, nil
380			}
381		}
382	
383		return true, nil
384	}
