12	// V2GitStore provides checkpoint storage operations for the v2 ref layout.
13	// It writes to two custom refs under refs/entire/:
14	//   - /main: permanent metadata + compact transcripts
15	//   - /full/current: active generation of raw transcripts
16	//
17	// V2GitStore is separate from GitStore (v1) to keep concerns isolated
18	// and simplify future v1 removal. It composes GitStore internally to
19	// reuse ref-agnostic entry-building helpers (tree surgery, session
20	// indexing, summary aggregation).
21	type V2GitStore struct {
22		repo *git.Repository
23		gs   *GitStore // shared entry-building helpers (same package)
24	
25		// maxCheckpointsPerGeneration overrides the rotation threshold for testing.
26		// Zero means use DefaultMaxCheckpointsPerGeneration.
27		maxCheckpointsPerGeneration int
28	
29		// FetchRemote is the git remote used for fetch-on-demand operations (e.g.,
30		// fetching /full/* refs during entire resume). Defaults to "origin".
31		// Set to the checkpoint remote URL when checkpoint_remote is configured.
32		FetchRemote string
33	}
34	
35	// maxCheckpoints returns the effective rotation threshold.
36	func (s *V2GitStore) maxCheckpoints() int {
37		if s.maxCheckpointsPerGeneration > 0 {
38			return s.maxCheckpointsPerGeneration
39		}
40		return DefaultMaxCheckpointsPerGeneration
41	}
42	
43	// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
44	// fetchRemote is the git remote used for fetch-on-demand operations (e.g., fetching
45	// /full/* refs during entire resume). Pass "origin" or the checkpoint remote URL.
46	func NewV2GitStore(repo *git.Repository, fetchRemote string) *V2GitStore {
47		if fetchRemote == "" {
48			fetchRemote = "origin"
49		}
50		return &V2GitStore{
51			repo:        repo,
52			gs:          &GitStore{repo: repo},
53			FetchRemote: fetchRemote,
54		}
55	}
56	
57	// ensureRef ensures that a custom ref exists, creating an orphan commit
58	// with an empty tree if it does not.
59	func (s *V2GitStore) ensureRef(ctx context.Context, refName plumbing.ReferenceName) error {
60		_, err := s.repo.Reference(refName, true)
61		if err == nil {
62			return nil // Already exists
63		}
64	
65		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
66		if err != nil {
67			return fmt.Errorf("failed to build empty tree: %w", err)
68		}
69	
70		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
71		commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
72		if err != nil {
73			return fmt.Errorf("failed to create initial commit: %w", err)
74		}
75	
76		ref := plumbing.NewHashReference(refName, commitHash)
77		if err := s.repo.Storer.SetReference(ref); err != nil {
78			return fmt.Errorf("failed to set ref %s: %w", refName, err)
79		}
80	
81		return nil
82	}
83	
84	// GetRefState returns the parent commit hash and root tree hash for a ref.
85	func (s *V2GitStore) GetRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
86		ref, err := s.repo.Reference(refName, true)
87		if err != nil {
88			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
89		}
90	
91		commit, err := s.repo.CommitObject(ref.Hash())
92		if err != nil {
93			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
94		}
95	
96		return ref.Hash(), commit.TreeHash, nil
97	}
98	
99	// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
100	func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
101		commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
102		if err != nil {
103			return fmt.Errorf("failed to create commit: %w", err)
104		}
105	
106		ref := plumbing.NewHashReference(refName, commitHash)
107		if err := s.repo.Storer.SetReference(ref); err != nil {
108			return fmt.Errorf("failed to update ref %s: %w", refName, err)
109		}
110	
111		return nil
112	}
