23	
24	// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
25	// When a generation reaches this many checkpoints, it is archived
26	// and a fresh /full/current is created.
27	const DefaultMaxCheckpointsPerGeneration = 100
28	
29	// GenerationMetadata tracks the state of a /full/* generation.
30	// Written to the tree root as generation.json at archive time only — not during
31	// normal writes to /full/current. This keeps /full/current free of root-level
32	// files, ensuring conflict-free tree merges during push recovery.
33	//
34	// The generation's sequence number is derived from the ref name, not stored here.
35	// Checkpoint membership is determined by walking the tree (shard directories).
36	type GenerationMetadata struct {
37		// OldestCheckpointAt is the creation time of the earliest checkpoint.
38		OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`
39	
40		// NewestCheckpointAt is the creation time of the most recent checkpoint.
41		NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
42	}
43	
44	// readGeneration reads generation.json from the given tree hash.
45	// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
46	func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
47		if treeHash == plumbing.ZeroHash {
48			return GenerationMetadata{}, nil
49		}
50	
51		tree, err := s.repo.TreeObject(treeHash)
52		if err != nil {
53			return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
54		}
55	
56		file, err := tree.File(paths.GenerationFileName)
57		if err != nil {
58			if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
59				return GenerationMetadata{}, nil
60			}
61			return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
62		}
63	
64		content, err := file.Contents()
65		if err != nil {
66			return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
67		}
68	
69		var gen GenerationMetadata
70		if err := json.Unmarshal([]byte(content), &gen); err != nil {
71			return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
72		}
73	
74		return gen, nil
75	}
76	
77	// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
78	func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
79		_, treeHash, err := s.GetRefState(refName)
80		if err != nil {
81			return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
82		}
83		return s.readGeneration(treeHash)
84	}
85	
86	// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
87	// Returns a TreeEntry ready to be placed in a tree.
88	func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
89		data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
90		if err != nil {
91			return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
92		}
93	
94		blobHash, err := CreateBlobFromContent(s.repo, data)
95		if err != nil {
96			return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
97		}
98	
99		return object.TreeEntry{
100			Name: paths.GenerationFileName,
101			Mode: filemode.Regular,
102			Hash: blobHash,
103		}, nil
104	}
105	
106	// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
107	func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
108		entry, err := s.marshalGenerationBlob(gen)
109		if err != nil {
110			return err
111		}
112		entries[paths.GenerationFileName] = entry
113		return nil
114	}
115	
116	// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
117	// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
118	// across all shard prefixes. Returns 0 for an empty tree.
119	func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
120		if treeHash == plumbing.ZeroHash {
121			return 0, nil
122		}
123	
124		tree, err := s.repo.TreeObject(treeHash)
125		if err != nil {
126			return 0, fmt.Errorf("failed to read tree: %w", err)
127		}
128	
129		count := 0
130		if err := WalkCheckpointShards(s.repo, tree, func(_ id.CheckpointID, _ plumbing.Hash) error {
131			count++
132			return nil
133		}); err != nil {
134			return 0, err
135		}
136	
137		return count, nil
138	}
139	
140	// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
141	// a new root tree hash. Preserves all existing entries (shard directories, etc.).
142	func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
143		entry, err := s.marshalGenerationBlob(gen)
144		if err != nil {
145			return plumbing.ZeroHash, err
146		}
147	
148		return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
149			UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
150	}
151	
152	// computeGenerationTimestamps derives timestamps for a generation being archived.
153	// Uses the commit history of the /full/current ref: oldest = first commit time,
154	// newest = latest commit time. Falls back to time.Now() if the ref has no history.
155	// Note: /full/* trees don't contain session metadata (that's on /main), so we
156	// derive timestamps from git commit times rather than walking the tree.
157	func (s *V2GitStore) computeGenerationTimestamps() GenerationMetadata {
158		now := time.Now().UTC()
159		fallback := GenerationMetadata{OldestCheckpointAt: now, NewestCheckpointAt: now}
160	
161		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
162		ref, err := s.repo.Reference(refName, true)
163		if err != nil {
164			return fallback
165		}
166	
167		commit, err := s.repo.CommitObject(ref.Hash())
168		if err != nil {
169			return fallback
170		}
171	
172		newest := commit.Committer.When.UTC()
173	
174		// Walk parents to find the oldest commit in this generation
175		iter := commit
176		for len(iter.ParentHashes) > 0 {
177			parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
178			if parentErr != nil {
179				break
180			}
181			iter = parent
182		}
183		oldest := iter.Committer.When.UTC()
184	
185		return GenerationMetadata{
186			OldestCheckpointAt: oldest,
187			NewestCheckpointAt: newest,
188		}
189	}
190	
191	// generationRefWidth is the zero-padded width of archived generation ref names.
192	const generationRefWidth = 13
193	
194	// GenerationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
195	var GenerationRefPattern = regexp.MustCompile(`^\d{13}$`)
196	
197	// listArchivedGenerations returns the names of all archived generation refs
198	// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
199	func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
200		refs, err := s.repo.References()
201		if err != nil {
202			return nil, fmt.Errorf("failed to list references: %w", err)
203		}
204	
205		var archived []string
206		err = refs.ForEach(func(ref *plumbing.Reference) error {
207			name := ref.Name().String()
208			if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
209				return nil
210			}
211			suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
212			if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
213				return nil
214			}
215			archived = append(archived, suffix)
216			return nil
217		})
218		if err != nil {
219			return nil, fmt.Errorf("failed to iterate references: %w", err)
220		}
221	
222		sort.Strings(archived)
223		return archived, nil
224	}
225	
226	// nextGenerationNumber returns the next sequential generation number for archiving.
227	// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
228	func (s *V2GitStore) nextGenerationNumber() (int, error) {
229		archived, err := s.ListArchivedGenerations()
230		if err != nil {
231			return 0, err
232		}
233	
234		var maxNum int64
235		for _, name := range archived {
236			n, parseErr := strconv.ParseInt(name, 10, 64)
237			if parseErr != nil {
238				continue // skip unparseable entries
239			}
240			if n > maxNum {
241				maxNum = n
242			}
243		}
244		return int(maxNum) + 1, nil
245	}
246	
247	// rotateGeneration archives the current /full/current generation and creates
248	// a fresh orphan. This is a 2-phase operation:
249	//
250	//  1. Archive: determine the next generation number, create a new ref pointing
251	//     to the current /full/current commit.
252	//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
253	//     point /full/current at it.
254	func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
255		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
256	
257		// Guard against concurrent rotation: re-read /full/current and check if
258		// it's still above the threshold. If not, another instance already rotated.
259		_, currentTreeHash, err := s.GetRefState(refName)
260		if err != nil {
261			return fmt.Errorf("rotation: failed to read /full/current: %w", err)
262		}
263		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
264		if err != nil {
265			return fmt.Errorf("rotation: failed to count checkpoints: %w", err)
266		}
267		if checkpointCount < s.maxCheckpoints() {
268			return nil
269		}
270	
271		currentRef, err := s.repo.Reference(refName, true)
272		if err != nil {
273			return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
274		}
275	
276		archiveNumber, err := s.nextGenerationNumber()
277		if err != nil {
278			return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
279		}
280	
281		// Phase 1: Archive — create ref pointing to the current commit.
282		// If the archive ref already exists, another instance already rotated — skip.
283		archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
284		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
285			logging.Info(ctx, "rotation: archive ref already exists, skipping",
286				slog.String("archive_ref", string(archiveRefName)),
287			)
288			return nil
289		}
290		archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
291		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
292			return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
293		}
294	
295		// Verify /full/current hasn't been advanced by another writer since we read it.
296		// If it changed, abort — the archive ref is harmless (points to a valid commit)
297		// and the next writer will trigger rotation again.
298		postArchiveRef, err := s.repo.Reference(refName, true)
299		if err != nil {
300			return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
301		}
302		if postArchiveRef.Hash() != currentRef.Hash() {
303			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
304			return nil
305		}
306	
307		// Write generation.json to the current tree before archiving.
308		gen := s.computeGenerationTimestamps()
309		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
310		if err != nil {
311			return fmt.Errorf("rotation: failed to add generation.json: %w", err)
312		}
313	
314		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
315		archiveCommitHash, err := CreateCommit(s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
316		if err != nil {
317			return fmt.Errorf("rotation: failed to create archive commit: %w", err)
318		}
319	
320		// Update the archive ref to point to the commit with generation.json
321		archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
322		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
323			return fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
324		}
325	
326		// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
327		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
328		if err != nil {
329			return fmt.Errorf("rotation: failed to build empty tree: %w", err)
330		}
331	
332		orphanCommitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
333		if err != nil {
334			return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
335		}
336	
337		orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
338		if err := s.repo.Storer.SetReference(orphanRef); err != nil {
339			return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
340		}
341	
342		logging.Info(ctx, "generation rotation complete",
343			slog.Int("archived_generation", archiveNumber),
344			slog.String("archive_ref", string(archiveRefName)),
345		)
346	
347		return nil
348	}
