1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"sync"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17	
18		"github.com/go-git/go-git/v6"
19		"github.com/go-git/go-git/v6/plumbing"
20		"github.com/go-git/go-git/v6/plumbing/object"
21	)
22	
23	// disconnectedOnce ensures the disconnection warning runs at most once per process.
24	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
25	
26	// IsMetadataDisconnected checks whether the local metadata branch
27	// and the provided fetched or remote-tracking ref exist but share no common
28	// ancestor.
29	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (bool, error) {
30		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
31		localRef, err := repo.Reference(refName, true)
32		if errors.Is(err, plumbing.ErrReferenceNotFound) {
33			return false, nil
34		}
35		if err != nil {
36			return false, fmt.Errorf("failed to check local metadata branch: %w", err)
37		}
38	
39		remoteRef, err := repo.Reference(remoteRefName, true)
40		if errors.Is(err, plumbing.ErrReferenceNotFound) {
41			return false, nil
42		}
43		if err != nil {
44			return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
45		}
46	
47		if localRef.Hash() == remoteRef.Hash() {
48			return false, nil
49		}
50	
51		repoPath, err := getRepoPath(repo)
52		if err != nil {
53			return false, err
54		}
55	
56		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
57	}
58	
59	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
60	// branch is disconnected and prints a warning to stderr if so.
61	// It does NOT fix the problem — users are directed to 'entire doctor'.
62	//
63	// Uses sync.Once, so a transient failure on the first call permanently suppresses
64	// the warning. This is acceptable because the check is advisory only and
65	// 'entire doctor' is the authoritative repair path.
66	func WarnIfMetadataDisconnected() {
67		disconnectedOnce.Do(func() {
68			ctx := context.Background()
69			repo, err := OpenRepository(ctx)
70			if err != nil {
71				logging.Debug(ctx, "metadata disconnection check: could not open repository",
72					slog.String("error", err.Error()))
73				return
74			}
75			disconnected, err := IsMetadataDisconnected(ctx, repo, plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName))
76			if err != nil {
77				logging.Debug(ctx, "metadata disconnection check failed",
78					slog.String("error", err.Error()))
79				return
80			}
81			if !disconnected {
82				return
83			}
84			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
85			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
86		})
87	}
88	
89	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
90	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
91	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
92	// and handled by the push path's tree merge.
93	//
94	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
95	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
96	// apply cleanly.
97	//
98	// Progress messages are written to w (typically os.Stderr for hooks or
99	// cmd.ErrOrStderr() for commands).
100	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
101	func ReconcileDisconnectedMetadataBranch(
102		ctx context.Context,
103		repo *git.Repository,
104		remoteRefName plumbing.ReferenceName,
105		w io.Writer,
106	) error {
107		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
108	
109		// Check local branch
110		localRef, err := repo.Reference(refName, true)
111		if errors.Is(err, plumbing.ErrReferenceNotFound) {
112			return nil // No local branch — nothing to reconcile
113		}
114		if err != nil {
115			return fmt.Errorf("failed to check local metadata branch: %w", err)
116		}
117	
118		// Check remote-tracking branch
119		remoteRef, err := repo.Reference(remoteRefName, true)
120		if errors.Is(err, plumbing.ErrReferenceNotFound) {
121			return nil // No remote branch — nothing to reconcile
122		}
123		if err != nil {
124			return fmt.Errorf("failed to check remote metadata branch: %w", err)
125		}
126	
127		localHash := localRef.Hash()
128		remoteHash := remoteRef.Hash()
129	
130		// Same hash — nothing to do
131		if localHash == remoteHash {
132			return nil
133		}
134	
135		// Check if disconnected using git merge-base
136		repoPath, err := getRepoPath(repo)
137		if err != nil {
138			return err
139		}
140	
141		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
142		if err != nil {
143			return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
144		}
145		if !disconnected {
146			// Shared ancestry (diverged or ancestor) — not our problem
147			return nil
148		}
149	
150		// Disconnected — cherry-pick local commits onto remote tip
151		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
152	
153		// Collect local commits oldest-first
154		localCommits, err := collectCommitChain(repo, localHash)
155		if err != nil {
156			return fmt.Errorf("failed to collect local commits: %w", err)
157		}
158	
159		// Filter out empty-tree commits (the orphan bug commit)
160		var dataCommits []*object.Commit
161		for _, c := range localCommits {
162			tree, treeErr := c.Tree()
163			if treeErr != nil {
164				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
165			}
166			if len(tree.Entries) > 0 {
167				dataCommits = append(dataCommits, c)
168			}
169		}
170	
171		if len(dataCommits) == 0 {
172			// Local only had empty orphan — just point to remote
173			ref := plumbing.NewHashReference(refName, remoteHash)
174			if err := repo.Storer.SetReference(ref); err != nil {
175				return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
176			}
177			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
178			return nil
179		}
180	
181		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
182	
183		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits)
184		if err != nil {
185			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
186		}
187	
188		// Update local branch ref
189		ref := plumbing.NewHashReference(refName, newTip)
190		if err := repo.Storer.SetReference(ref); err != nil {
191			return fmt.Errorf("failed to update metadata branch: %w", err)
192		}
193	
194		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
195		return nil
196	}
197	
198	// isDisconnected checks if two commits have no common ancestor using git merge-base.
199	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
200	// or (false, error) if git merge-base failed for another reason.
201	//
202	// git merge-base exit codes:
203	//   - 0: common ancestor found (shared ancestry)
204	//   - 1: no common ancestor (disconnected)
205	//   - 128+: error (corrupt repo, invalid hash, etc.)
206	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
207		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
208		defer cancel()
209		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
210		cmd.Dir = repoPath
211		if err := cmd.Run(); err != nil {
212			var exitErr *exec.ExitError
213			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
214				return true, nil // No common ancestor — disconnected
215			}
216			return false, fmt.Errorf("git merge-base failed: %w", err)
217		}
218		return false, nil // Shared ancestry
219	}
220	
221	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
222	func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
223		var chain []*object.Commit
224		current := tip
225	
226		reachedRoot := false
227		for range MaxCommitTraversalDepth {
228			commit, err := repo.CommitObject(current)
229			if err != nil {
230				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
231			}
232			chain = append(chain, commit)
233	
234			if len(commit.ParentHashes) == 0 {
235				reachedRoot = true
236				break
237			}
238			current = commit.ParentHashes[0]
239		}
240	
241		if !reachedRoot {
242			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
243		}
244	
245		// Reverse to oldest-first
246		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
247			chain[i], chain[j] = chain[j], chain[i]
248		}
249	
250		return chain, nil
251	}
252	
253	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
254	// For each commit, it computes the full diff from its parent (additions, modifications,
255	// and deletions), then applies that delta onto the current tip's tree.
256	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
257		currentTip := base
258	
259		for _, commit := range commits {
260			// Get the commit's tree entries
261			commitTree, err := commit.Tree()
262			if err != nil {
263				return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
264			}
265	
266			commitEntries := make(map[string]object.TreeEntry)
267			if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
268				return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
269			}
270	
271			// Get parent's tree entries (empty if root commit)
272			parentEntries := make(map[string]object.TreeEntry)
273			if len(commit.ParentHashes) > 0 {
274				parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
275				if pErr != nil {
276					return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
277				}
278				parentTree, ptErr := parentCommit.Tree()
279				if ptErr != nil {
280					return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
281				}
282				if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
283					return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
284				}
285			}
286	
287			// Compute full delta: additions, modifications, and deletions
288			added := make(map[string]object.TreeEntry)
289			for path, entry := range commitEntries {
290				parentEntry, exists := parentEntries[path]
291				if !exists || parentEntry.Hash != entry.Hash {
292					added[path] = entry // New or modified
293				}
294			}
295			var deleted []string
296			for path := range parentEntries {
297				if _, exists := commitEntries[path]; !exists {
298					deleted = append(deleted, path) // Removed in this commit
299				}
300			}
301	
302			if len(added) == 0 && len(deleted) == 0 {
303				continue // Skip no-op commits
304			}
305	
306			// Get current tip's tree and apply delta
307			tipCommit, err := repo.CommitObject(currentTip)
308			if err != nil {
309				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
310			}
311			tipTree, err := tipCommit.Tree()
312			if err != nil {
313				return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
314			}
315	
316			mergedEntries := make(map[string]object.TreeEntry)
317			if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
318				return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
319			}
320			for path, entry := range added {
321				mergedEntries[path] = entry
322			}
323			for _, path := range deleted {
324				delete(mergedEntries, path)
325			}
326	
327			mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, mergedEntries)
328			if err != nil {
329				return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
330			}
331	
332			// Create new commit on top of current tip, preserving original message/author
333			newHash, err := createCherryPickCommit(repo, mergedTreeHash, currentTip, commit)
334			if err != nil {
335				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
336			}
337	
338			currentTip = newHash
339		}
340	
341		return currentTip, nil
342	}
