344	// createCherryPickCommit creates a new commit on top of parent, preserving the
345	// original commit's message and author.
346	func createCherryPickCommit(repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
347		committerName, committerEmail := GetGitAuthorFromRepo(repo)
348		now := time.Now()
349	
350		commit := &object.Commit{
351			TreeHash:     treeHash,
352			ParentHashes: []plumbing.Hash{parent},
353			Author:       original.Author,
354			Committer: object.Signature{
355				Name:  committerName,
356				Email: committerEmail,
357				When:  now,
358			},
359			Message: original.Message,
360		}
361	
362		obj := repo.Storer.NewEncodedObject()
363		if err := commit.Encode(obj); err != nil {
364			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
365		}
366	
367		hash, err := repo.Storer.SetEncodedObject(obj)
368		if err != nil {
369			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
370		}
371	
372		return hash, nil
373	}
374	
375	// getRepoPath returns the filesystem path for the repository's worktree.
376	func getRepoPath(repo *git.Repository) (string, error) {
377		wt, err := repo.Worktree()
378		if err != nil {
379			return "", fmt.Errorf("failed to get worktree: %w", err)
380		}
381		return wt.Filesystem.Root(), nil
382	}
